def _get_chrome_aes_key(profile_dir: Optional[Path] = None) -> Optional[bytes]:
    """Load and decrypt Chrome's AES-GCM cookie encryption key from Local State."""
    try:
        import Cryptodome.Cipher.AES as _AES  # type: ignore[import]
    except ImportError:
        try:
            from Crypto.Cipher import AES as _AES  # type: ignore[import]
        except ImportError:
            return None  # pycryptodome not available

    local_state_path = (profile_dir or _CHROME_PROFILE_PATH) / "Local State"
    if not local_state_path.exists():
        return None
    try:
        state = json.loads(local_state_path.read_text(encoding="utf-8"))
        enc_key_b64 = state["os_crypt"]["encrypted_key"]
        enc_key = base64.b64decode(enc_key_b64)
        # Strip the "DPAPI" prefix (first 5 bytes)
        if not enc_key.startswith(b"DPAPI"):
            return None
        return _dpapi_decrypt(enc_key[5:])
    except Exception as exc:
        logger.debug("Failed to get Chrome AES key: %s", exc)
        return None

def _get_cookies(self) -> Dict[str, str]:
    """Load GitHub cookies from GoogleAccountPool or fallback JSON.

    Returns:
        Mapping of cookie name to value.

    Raises:
        RuntimeError: If no cookies are available for the account.
    """
    # Primary: account pool
    try:
        from engine.integrations.google_account_pool import get_account_pool

        pool = get_account_pool()
        account = pool.get_by_name(self.account_name)
        if account and "github" in account.services and account.cookies:
            return dict(account.cookies)
    except Exception as exc:
        logger.debug("Could not load cookies from account pool: %s", exc)

    # Fallback: JSON file
    json_path = os.path.join(
        _FALLBACK_COOKIES_DIR,
        f"github_{self.account_name}_cookies.json",
    )
    if os.path.exists(json_path):
        try:
            with open(json_path, "r", encoding="utf-8") as fh:
                cookies = json.load(fh)
            if isinstance(cookies, dict) and cookies:
                logger.debug(
                    "Loaded %d cookies from %s", len(cookies), json_path
                )
                return cookies
        except Exception as exc:
            logger.debug("Could not load fallback cookies from %s: %s", json_path, exc)

    raise RuntimeError(
        f"No GitHub cookies available for account '{self.account_name}'. "
        f"Import cookies via GithubAccountImporter or place them at {json_path}."
    )

