def _run(
    self, args: List[str], timeout: int = 30
) -> ExecResult:
    """Run a gh CLI command.

    Args:
        args: Arguments after ``gh``.
        timeout: Maximum execution time.

    Returns:
        ExecResult with command output.
    """
    cmd = [self._gh] + args
    logger.debug("Running: %s", " ".join(cmd))
    try:
        proc = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=timeout,
        )
        return ExecResult(
            stdout=proc.stdout,
            stderr=proc.stderr,
            returncode=proc.returncode,
        )
    except subprocess.TimeoutExpired:
        logger.warning("Command timed out after %ds: %s", timeout, " ".join(cmd))
        return ExecResult(
            stderr=f"Command timed out after {timeout}s",
            returncode=-1,
            timed_out=True,
        )
    except FileNotFoundError:
        logger.error("gh CLI not found at %s", self._gh)
        return ExecResult(
            stderr=f"gh CLI not found at {self._gh}",
            returncode=-1,
        )

def _emit_event(
    self,
    character_id: str,
    changes: Dict,
    snapshot: Dict,
    scene: str,
    source: str,
) -> None:
    """Emit state_changed event to ActivityBus and registered listeners."""
    event = {
        "type": "state_changed",
        "character_id": character_id,
        "changes": changes,
        "scene": scene,
        "source": source,
        "timestamp": time.time(),
    }

    # Notify registered listeners
    for listener in self._listeners:
        try:
            listener(event, snapshot)
        except Exception as exc:
            logger.debug("StateCoordinator: listener error: %s", exc)

    # Emit to ActivityBus
    try:
        from engine.services.activity_bus import get_activity_bus, Activity
        bus = get_activity_bus()
        bus.push(Activity(
            activity_type="state_changed",
            description=(
                f"{character_id}: {', '.join(f'{k}={v}' for k, v in changes.items())}"
            ),
            metadata={
                "character_id": character_id,
                "changes": {k: v for k, v in changes.items()
                            if isinstance(v, (int, float, str, bool))},
                "scene": scene,
                "source": source,
            },
        ))
    except Exception:
        logger.debug("ActivityBus is optional", exc_info=True)

