    payload = json.dumps([self._locale, None, None, None, 4, None, None, [2, 4, 7, 19], None, []])
    results = self._call("ku4Jyf", payload)
    prompts = []
    try:
        for item in results[0][0]:
            prompts.append({
                "title": item[0],
